//! The store's files: the generated messages, and reading each file into a checked row.
//!
//! Every reader checks the schema (refusing a newer one and a missing one) and the state
//! (refusing a value it does not know), and ignores fields it does not know (protobuf does).

use std::path::{Path, PathBuf};

use prost::Message;

use super::{Claims, RequestState, StoreError};
use crate::ca::P256Key;
use crate::names::{HostId, KeyHash};

/// The store's messages, generated by build.rs from proto/.
#[allow(
    clippy::all,
    dead_code,
    reason = "generated code follows the proto's shapes and comments, not clippy's style, and \
              carries accessors and enum conversions the store does not call"
)]
pub(crate) mod pb {
    include!(concat!(
        env!("OUT_DIR"),
        "/hostkeeper.enrollment.store.v1.rs"
    ));
}

/// The schema this release writes and the newest it reads.
pub(crate) const SCHEMA: u32 = 1;

pub(crate) fn corrupt(path: &Path, reason: &str) -> StoreError {
    StoreError::Corrupt {
        path: path.to_path_buf(),
        reason: reason.to_owned(),
    }
}

/// Decodes `bytes` and checks the schema `schema_of` reads from it.
fn decode<M: Message + Default>(
    path: &Path,
    bytes: &[u8],
    schema_of: fn(&M) -> u32,
) -> Result<M, StoreError> {
    let message = M::decode(bytes).map_err(|e| corrupt(path, &e.to_string()))?;
    check_schema(path, schema_of(&message))?;
    Ok(message)
}

fn check_schema(path: &Path, schema: u32) -> Result<(), StoreError> {
    if schema == 0 {
        return Err(corrupt(path, "the file has no schema"));
    }
    if schema > SCHEMA {
        return Err(StoreError::NewerSchema {
            path: path.to_path_buf(),
            schema,
        });
    }
    Ok(())
}

/// `text` as an optional host id: empty is none.
pub(crate) fn optional_host(path: &Path, text: &str) -> Result<Option<HostId>, StoreError> {
    if text.is_empty() {
        return Ok(None);
    }
    HostId::parse(text)
        .map(Some)
        .map_err(|e| corrupt(path, &e.to_string()))
}

/// A request file.
#[derive(Clone, Debug)]
pub(crate) struct RequestRow {
    pub path: PathBuf,
    pub pb: pb::Request,
    pub id: KeyHash,
    pub key: P256Key,
    pub state: RequestState,
}

impl RequestRow {
    /// Reads the request file `path` of request `id`.
    pub fn read(path: &Path, bytes: &[u8], id: &KeyHash) -> Result<RequestRow, StoreError> {
        let pb: pb::Request = decode(path, bytes, |m: &pb::Request| m.schema)?;
        let state = RequestState::from_number(pb.state).ok_or(StoreError::UnknownState {
            path: path.to_path_buf(),
            value: pb.state,
        })?;
        let key = P256Key::from_spki(&pb.spki_der)
            .ok()
            .filter(|key| key.key_hash() == *id && pb.request_id == id.as_bytes())
            .ok_or(corrupt(
                path,
                "the request's key is not the one its id names",
            ))?;
        Ok(RequestRow {
            path: path.to_path_buf(),
            pb,
            id: *id,
            key,
            state,
        })
    }

    /// The machine id the request claims.
    pub fn machine_id(&self) -> &str {
        self.pb
            .claims
            .as_ref()
            .map_or("", |claims| &claims.machine_id)
    }

    /// The Mac serial number the request claims; empty when it claims none.
    pub fn mac_serial(&self) -> &str {
        self.pb
            .claims
            .as_ref()
            .map_or("", |claims| &claims.mac_serial)
    }

    /// The host this request renews.
    pub fn renewal_of(&self) -> Result<Option<HostId>, StoreError> {
        optional_host(&self.path, &self.pb.renewal_of)
    }

    /// The host id it was approved as.
    pub fn host_id(&self) -> Result<Option<HostId>, StoreError> {
        let text = self
            .pb
            .approved
            .as_ref()
            .map_or("", |approved| &approved.host_id);
        optional_host(&self.path, text)
    }

    /// Sets the state, in the row and in its message.
    pub fn set_state(&mut self, state: RequestState) {
        self.state = state;
        self.pb.state = state as i32;
    }
}

/// A host file.
#[derive(Clone, Debug)]
pub(crate) struct HostRow {
    pub pb: pb::Host,
    pub key: KeyHash,
}

impl HostRow {
    pub fn read(path: &Path, bytes: &[u8]) -> Result<HostRow, StoreError> {
        let pb: pb::Host = decode(path, bytes, |m: &pb::Host| m.schema)?;
        let key = KeyHash::from_bytes(&pb.key_hash)
            .ok_or(corrupt(path, "the key hash is not 32 bytes"))?;
        Ok(HostRow { pb, key })
    }
}

/// Where a deny row is. The numbers are those of `DenyState` in the store's proto.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(i32)]
pub(crate) enum DenyState {
    Retiring = 1,
    Retired = 2,
    Cleared = 3,
}

impl DenyState {
    const ALL: [DenyState; 3] = [DenyState::Retiring, DenyState::Retired, DenyState::Cleared];

    /// Denied: retiring or retired.
    pub fn is_active(self) -> bool {
        self != DenyState::Cleared
    }
}

/// The state of the deny file `path`.
pub(crate) fn read_deny(path: &Path, bytes: &[u8]) -> Result<DenyState, StoreError> {
    let pb: pb::Deny = decode(path, bytes, |m: &pb::Deny| m.schema)?;
    DenyState::ALL
        .into_iter()
        .find(|state| *state as i32 == pb.state)
        .ok_or(StoreError::UnknownState {
            path: path.to_path_buf(),
            value: pb.state,
        })
}

/// The issued file `path`.
pub(crate) fn read_issued(path: &Path, bytes: &[u8]) -> Result<pb::Issued, StoreError> {
    decode(path, bytes, |m: &pb::Issued| m.schema)
}

/// The Mac nonce file `path`.
pub(crate) fn read_mac_nonce(path: &Path, bytes: &[u8]) -> Result<pb::MacNonce, StoreError> {
    decode(path, bytes, |m: &pb::MacNonce| m.schema)
}

/// The next serial of the counter file `path`.
pub(crate) fn read_serial(path: &Path, bytes: &[u8]) -> Result<u64, StoreError> {
    let pb: pb::SerialCounter = decode(path, bytes, |m: &pb::SerialCounter| m.schema)?;
    Ok(pb.next)
}

pub(crate) fn claims_to_pb(claims: &Claims) -> pb::Claims {
    pb::Claims {
        machine_id: claims.machine_id.clone(),
        dmi_serial: claims.dmi_serial.clone(),
        dmi_product_uuid: claims.dmi_product_uuid.clone(),
        addresses: claims.addresses.clone(),
        mac_serial: claims.mac_serial.clone(),
        mac_platform_uuid: claims.mac_platform_uuid.clone(),
        bmc_mac: claims.bmc_mac.clone(),
    }
}

pub(crate) fn claims_of_pb(claims: Option<&pb::Claims>) -> Claims {
    claims.map_or_else(Claims::default, |claims| Claims {
        machine_id: claims.machine_id.clone(),
        dmi_serial: claims.dmi_serial.clone(),
        dmi_product_uuid: claims.dmi_product_uuid.clone(),
        addresses: claims.addresses.clone(),
        mac_serial: claims.mac_serial.clone(),
        mac_platform_uuid: claims.mac_platform_uuid.clone(),
        bmc_mac: claims.bmc_mac.clone(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Catches the Rust states drifting from the proto's numbers, which would make a file
    /// written by one release read as another state by the next.
    #[test]
    fn the_states_carry_the_proto_numbers() {
        let requests = [
            (RequestState::Pending, pb::RequestState::Pending),
            (
                RequestState::DuplicateClaim,
                pb::RequestState::DuplicateClaim,
            ),
            (RequestState::Approved, pb::RequestState::Approved),
            (RequestState::Issued, pb::RequestState::Issued),
            (RequestState::Denied, pb::RequestState::Denied),
        ];
        for (state, proto) in requests {
            assert_eq!(state as i32, proto as i32, "{state:?}");
            assert_eq!(RequestState::from_number(proto as i32), Some(state));
        }
        assert_eq!(
            RequestState::from_number(pb::RequestState::Unspecified as i32),
            None
        );
        let denies = [
            (DenyState::Retiring, pb::DenyState::Retiring),
            (DenyState::Retired, pb::DenyState::Retired),
            (DenyState::Cleared, pb::DenyState::Cleared),
        ];
        for (state, proto) in denies {
            assert_eq!(state as i32, proto as i32, "{state:?}");
        }
    }
}
